using Waher.Runtime.Profiling;

namespace Waher.Security.PQC.Test
{
	/// <summary>
	/// Signature mode.
	/// </summary>
	public enum SignatureMode
	{
		/// <summary>
		/// External signature interface
		/// </summary>
		External,

		/// <summary>
		/// Internal signature interface
		/// </summary>
		Internal,

		/// <summary>
		/// Internal signature interface, with a precomputed μ
		/// </summary>
		Precomputedμ
	}

	[TestClass]
	public sealed class ML_DSA_Tests
	{
		private static readonly Random rnd = new();
		private const int q = 8380417;

		[TestMethod]
		[DataRow(256, 2, 2, false, 0, 3 * 32)]
		[DataRow(256, 2, 2, false, 1, 3 * 32)]
		[DataRow(256, 2, 2, false, 2, 3 * 32)]
		[DataRow(256, 2, 2, false, 3, 3 * 32)]
		[DataRow(256, 2, 2, false, 4, 3 * 32)]
		[DataRow(256, 2, 2, true, 0, 3 * 32)]
		[DataRow(256, 4, 4, false, 0, 4 * 32)]
		[DataRow(256, 4, 4, false, 1, 4 * 32)]
		[DataRow(256, 4, 4, false, 2, 4 * 32)]
		[DataRow(256, 4, 4, false, 3, 4 * 32)]
		[DataRow(256, 4, 4, false, 4, 4 * 32)]
		[DataRow(256, 4, 4, false, 5, 4 * 32)]
		[DataRow(256, 4, 4, false, 6, 4 * 32)]
		[DataRow(256, 4, 4, false, 7, 4 * 32)]
		[DataRow(256, 4, 4, false, 8, 4 * 32)]
		[DataRow(256, 4, 4, false, 9, 4 * 32)]
		[DataRow(256, 4, 4, true, 0, 4 * 32)]
		[DataRow(256, (1 << 12) - 1, 1 << 12, false, 0, 13 * 32)]
		[DataRow(256, (1 << 12) - 1, 1 << 12, false, 1, 13 * 32)]
		[DataRow(256, (1 << 12) - 1, 1 << 12, false, 10, 13 * 32)]
		[DataRow(256, (1 << 12) - 1, 1 << 12, false, 100, 13 * 32)]
		[DataRow(256, (1 << 12) - 1, 1 << 12, false, 1000, 13 * 32)]
		[DataRow(256, (1 << 12) - 1, 1 << 12, false, 5000, 13 * 32)]
		[DataRow(256, (1 << 12) - 1, 1 << 12, true, 0, 13 * 32)]
		public void Test_01_BitPackUnpackShort(int n, int a, int b, bool Random, int ValueOffset,
			int ExpectedNrBytes)
		{
			short[] Values = new short[n];
			int i;

			for (i = 0; i < n; i++)
			{
				if (Random)
					Values[i] = (short)(rnd.Next(0, b + a + 1) - a);
				else
					Values[i] = (short)((i + ValueOffset) % (b + a) - a);
			}

			byte[] Output = new byte[ExpectedNrBytes];
			int NrBytes = ML_DSA.BitPack(Values, Output, 0, (uint)a, (uint)b);

			Assert.AreEqual(ExpectedNrBytes, NrBytes, "Unexpected number of bytes generated.");

			short[] Values2 = new short[n];
			int NrBytes2 = ML_DSA.BitUnpack(Values2, Output, 0, (uint)a, (uint)b);

			Assert.AreEqual(ExpectedNrBytes, NrBytes2, "Unexpected number of bytes decoded.");

			for (i = 0; i < n; i++)
				Assert.AreEqual(Values[i], Values2[i], "Unexpected decoded value at index " + i + ".");
		}

		[TestMethod]
		[DataRow(1, 0x10000000, 0x10000000, false, 0, 4)]
		[DataRow(256, 2, 2, false, 0, 3 * 32)]
		[DataRow(256, 2, 2, false, 1, 3 * 32)]
		[DataRow(256, 2, 2, false, 2, 3 * 32)]
		[DataRow(256, 2, 2, false, 3, 3 * 32)]
		[DataRow(256, 2, 2, false, 4, 3 * 32)]
		[DataRow(256, 2, 2, true, 0, 3 * 32)]
		[DataRow(256, 4, 4, false, 0, 4 * 32)]
		[DataRow(256, 4, 4, false, 1, 4 * 32)]
		[DataRow(256, 4, 4, false, 2, 4 * 32)]
		[DataRow(256, 4, 4, false, 3, 4 * 32)]
		[DataRow(256, 4, 4, false, 4, 4 * 32)]
		[DataRow(256, 4, 4, false, 5, 4 * 32)]
		[DataRow(256, 4, 4, false, 6, 4 * 32)]
		[DataRow(256, 4, 4, false, 7, 4 * 32)]
		[DataRow(256, 4, 4, false, 8, 4 * 32)]
		[DataRow(256, 4, 4, false, 9, 4 * 32)]
		[DataRow(256, 4, 4, true, 0, 4 * 32)]
		[DataRow(256, (1 << 19) - 1, 1 << 19, false, 0, 20 * 32)]
		[DataRow(256, (1 << 19) - 1, 1 << 19, false, 1, 20 * 32)]
		[DataRow(256, (1 << 19) - 1, 1 << 19, false, 10, 20 * 32)]
		[DataRow(256, (1 << 19) - 1, 1 << 19, false, 100, 20 * 32)]
		[DataRow(256, (1 << 19) - 1, 1 << 19, false, 1000, 20 * 32)]
		[DataRow(256, (1 << 19) - 1, 1 << 19, false, 10000, 20 * 32)]
		[DataRow(256, (1 << 19) - 1, 1 << 19, false, 100000, 20 * 32)]
		[DataRow(256, (1 << 19) - 1, 1 << 19, false, 500000, 20 * 32)]
		[DataRow(256, (1 << 19) - 1, 1 << 19, true, 0, 20 * 32)]
		public void Test_02_BitPackUnpackInt(int n, int a, int b, bool Random, int ValueOffset,
			int ExpectedNrBytes)
		{
			uint[] Values = new uint[n];
			int i, j;

			for (i = 0; i < n; i++)
			{
				if (Random)
					j = rnd.Next(0, b + a + 1) - a;
				else
					j = (i + ValueOffset) % (b + a + 1) - a;

				Values[i] = (uint)j;
			}

			byte[] Output = new byte[ExpectedNrBytes];
			int NrBytes = ML_DSA.BitPack(Values, Output, 0, (uint)a, (uint)b, false);

			Assert.AreEqual(ExpectedNrBytes, NrBytes, "Unexpected number of bytes generated.");

			uint[] Values2 = new uint[n];
			int NrBytes2 = ML_DSA.BitUnpack(Values2, Output, 0, (uint)a, (uint)b, false);

			Assert.AreEqual(ExpectedNrBytes, NrBytes2, "Unexpected number of bytes decoded.");

			for (i = 0; i < n; i++)
				Assert.AreEqual(Values[i] % q, Values2[i] % q, "Unexpected decoded value at index " + i + ".");
		}

