			"")]
		public void Test_04_Sign(string TestCase, string ModelName, SignatureMode SignatureMode,
			string Input, string Rnd, string PublicKey, string PrivateKey, string Context,
			string HashAlgorithm, string Signature)
		{
			byte[] InputBin = Hashes.StringToBinary(Input);
			byte[] PublicKeyBin = Hashes.StringToBinary(PublicKey);
			byte[] PrivateKeyBin = Hashes.StringToBinary(PrivateKey);
			byte[]? ContextBin = Context is null ? null : Hashes.StringToBinary(Context);
			byte[]? RndBin = string.IsNullOrEmpty(Rnd) ? null : Hashes.StringToBinary(Rnd);
			byte[] SignatureBin = Hashes.StringToBinary(Signature);

			Console.Out.WriteLine("Test Case: " + TestCase);
			Console.Out.WriteLine("Model: " + ModelName);
			Console.Out.WriteLine("SignatureMode: " + SignatureMode);
			Console.Out.WriteLine("Input: " + Input);
			Console.Out.WriteLine("Rnd: " + Rnd);
			Console.Out.WriteLine("Public Key: " + PublicKey);
			Console.Out.WriteLine("Private Key: " + PrivateKey);
			Console.Out.WriteLine("Context: " + Context);
			Console.Out.WriteLine("Hash Algorithm: " + HashAlgorithm);
			Console.Out.WriteLine("Expected Signature: " + Signature);

			ML_DSA Model = ML_DSA.GetModel(ModelName);
			byte[] Result;
			int RejectionCount;
			bool Valid;

			if (SignatureMode == SignatureMode.Precomputedμ)
			{
				if (!string.IsNullOrEmpty(Context))
					Assert.Fail("Precomputed μ cannot have a context.");

				Result = Model.Sign_Internal(PrivateKeyBin, InputBin, true, RndBin,
					out RejectionCount);

				Valid = Model.Verify_Internal(PublicKeyBin, InputBin, true, Result);
			}
			else if (SignatureMode == SignatureMode.Internal)
			{
				if (!string.IsNullOrEmpty(Context))
					Assert.Fail("Precomputed μ cannot have a context.");

				Result = Model.Sign_Internal(PrivateKeyBin, InputBin, false, RndBin,
					out RejectionCount);

				Valid = Model.Verify_Internal(PublicKeyBin, InputBin, false, Result);
			}
			else if (string.IsNullOrEmpty(HashAlgorithm))
			{
				Result = Model.Sign(PrivateKeyBin, InputBin, ContextBin, RndBin,
					out RejectionCount);

				Valid = Model.Verify(PublicKeyBin, InputBin, Result, ContextBin);
			}
			else
			{
				switch (HashAlgorithm)
				{
					case "SHA2-512/224":
					case "SHA2-512/256":
					case "SHA2-224":
						Assert.Inconclusive("Hash Algorithm not supported: " + HashAlgorithm);
						break;
				}

				Result = Model.Sign(PrivateKeyBin, InputBin, ContextBin, RndBin,
					HashAlgorithm, out RejectionCount);

				Valid = Model.Verify(PublicKeyBin, InputBin, Result, ContextBin, HashAlgorithm);
			}

			Console.Out.WriteLine("Signature: " + Hashes.BinaryToString(Result).ToUpper());
			Console.Out.WriteLine("# Rejections: " + RejectionCount);

			int i, c = SignatureBin.Length;
			if (Result.Length != c)
				Assert.Fail("Signature length mismatch.");

			int NrSame = 0;
			int NrDifferent = 0;

			for (i = 0; i < c; i++)
			{
				if (SignatureBin[i] == Result[i])
					NrSame++;
				else
					NrDifferent++;
			}

			if (NrDifferent != 0)
			{
				double p = 100.0 * NrDifferent / c;

				if (!Valid)
				{
					Assert.Fail("Signature not valid. " +
						p.ToString("F1") + "% of signature bytes different.");
				}
				else
					Assert.Fail(p.ToString("F1") + "% of signature bytes different. (Signature valid however.)");
			}
		}

