		[TestMethod]
		public void Test_12_Benchmarking_GenKey()
		{
			Benchmarker1D? Benchmarker = null;

			for (int i = 0; i < 2; i++)
			{
				Benchmarker?.Dispose();
				Benchmarker = new();

				foreach (string ModelName in new string[] { "ML-DSA-44", "ML-DSA-65", "ML-DSA-87" })
				{
					ML_DSA Model = ML_DSA.GetModel(ModelName);
					using Benchmarking Benchmarking = Benchmarker.Start(ModelName);

					for (int j = 0; j < 1000; j++)
						Model.KeyGen();
				}
			}

			Console.Out.WriteLine(Benchmarker!.GetResultScriptMilliseconds());
		}

		[TestMethod]
		public void Test_13_Benchmarking_Sign()
		{
			Random Rnd = new();
			Benchmarker2D? Benchmarker = null;

			for (int i = 0; i < 2; i++)
			{
				Benchmarker?.Dispose();
				Benchmarker = new();

				foreach (string ModelName in new string[] { "ML-DSA-44", "ML-DSA-65", "ML-DSA-87" })
				{
					ML_DSA Model = ML_DSA.GetModel(ModelName);
					ML_DSA_Keys Keys = Model.KeyGen();

					foreach (int MessageSize in new int[] { 100, 1000, 10000 })
					{
						using Benchmarking Benchmarking = Benchmarker.Start(ModelName, MessageSize);

						for (int j = 0; j < 1000; j++)
						{
							byte[] Message = new byte[MessageSize];
							Rnd.NextBytes(Message);

							Model.Sign(Keys.PrivateKey, Message, out int RejectionCount);
						}
					}
				}
			}

			Console.Out.WriteLine(Benchmarker!.GetResultScriptMilliseconds());
		}

		[TestMethod]
		public void Test_14_Benchmarking_Verify()
		{
			Random Rnd = new();
			Benchmarker2D? Benchmarker = null;

			for (int i = 0; i < 2; i++)
			{
				Benchmarker?.Dispose();
				Benchmarker = new();

				foreach (string ModelName in new string[] { "ML-DSA-44", "ML-DSA-65", "ML-DSA-87" })
				{
					ML_DSA Model = ML_DSA.GetModel(ModelName);
					ML_DSA_Keys Keys = Model.KeyGen();

					foreach (int MessageSize in new int[] { 100, 1000, 10000 })
					{
						byte[][] Messages = new byte[1000][];
						byte[][] Signatures = new byte[1000][];

						for (int j = 0; j < 1000; j++)
						{
							Messages[j] = new byte[MessageSize];
							Rnd.NextBytes(Messages[j]);

							Signatures[j] = Model.Sign(Keys.PrivateKey, Messages[j], out int RejectionCount);
						}

						using Benchmarking Benchmarking = Benchmarker.Start(ModelName, MessageSize);

						for (int j = 0; j < 1000; j++)
							Model.Verify(Keys.PrivateKey, Messages[j], Signatures[j]);
					}
				}
			}

			Console.Out.WriteLine(Benchmarker!.GetResultScriptMilliseconds());
		}

		[TestMethod]
		public void Test_15_Benchmarking_SignAndVerify()
		{
			Random Rnd = new();
			Benchmarker2D? Benchmarker = null;

			for (int i = 0; i < 2; i++)
			{
				Benchmarker?.Dispose();
				Benchmarker = new();

				foreach (string ModelName in new string[] { "ML-DSA-44", "ML-DSA-65", "ML-DSA-87" })
				{
					ML_DSA Model = ML_DSA.GetModel(ModelName);
					ML_DSA_Keys Keys = Model.KeyGen();

					foreach (int MessageSize in new int[] { 100, 1000, 10000 })
					{
						int NrSignatures = 0;
						int NrRejections = 0;

						using (Benchmarking Benchmarking = Benchmarker.Start(ModelName, MessageSize))
						{
							for (int j = 0; j < 1000; j++)
							{
								byte[] Message = new byte[MessageSize];
								Rnd.NextBytes(Message);

								byte[] Signature;

								do
								{
									Signature = Model.Sign(Keys.PrivateKey, Message, out int RejectionCount);
									NrSignatures++;
									NrRejections += RejectionCount;
								}
								while (!Model.Verify(Keys.PublicKey, Message, Signature));
							}
						}

						Console.Out.WriteLine(ModelName);
						Console.Out.WriteLine("Recalculations: " + (NrSignatures - 1000));
						Console.Out.WriteLine("Rejections: " + NrRejections);
						Console.Out.WriteLine();
					}
				}
			}

			Console.Out.WriteLine(Benchmarker!.GetResultScriptMilliseconds());
		}


